head.script:
// scwin.onpageload에서 btn_save, btn_edit, btn_delete 오류 발생 방지 및 정확한 컴포넌트 참조
scwin.onpageload = function() {
    // 테스트결함관리 readOnly false (HTML에 grp_defInfo 없음. 필요시 추가하거나 관련 로직 제거)
    // if (grp_defInfo) grp_defInfo.setReadOnly(false); // grp_defInfo는 팝업 내에 있으므로, 이 부분은 팝업 관련 로직에서 제어

    // 초기 로드 시 메인 화면의 '조회'와 '등록' 버튼만 보이게 설정 (btn_search, reg_btn)
    // HTML을 보면 메인 화면에는 btn_save, btn_edit, btn_delete ID를 가진 요소가 직접적으로 없습니다.
    // 이는 팝업 내부의 버튼들인 'btn_save' (팝업용 저장), 'btn_popup_edit', 'btn_popup_delete'와 혼동된 것으로 보입니다.
    // 따라서 메인 화면 로드 시의 버튼 제어는 팝업 내부 버튼이 아닌, 메인 화면의 버튼에 초점을 맞춰야 합니다.
    // 현재 메인 화면에는 '조회' (btn_search)와 '등록' (reg_btn) 버튼만 명확하게 ID가 부여되어 있습니다.
    // 이들은 기본적으로 보여야 하므로 별도로 show/hide 로직을 추가할 필요는 없습니다.

    // 페이지 정보 초기화
    scwin.initPaginationInfo();

    // 전체 데이터 조회를 위해 페이지 크기를 크게 설정
    dmp_defVo.set("pageIndex", "1");
    dmp_defVo.set("pageSize", "1000"); // 충분히 큰 수로 설정

    // search_box : searchComp_1 이 없으면 search_box 숨김
    var searchBoxComp = $p.getComponentById("search_box");
    var searchComp1 = $p.getComponentById("searchComp_1");
    if (searchBoxComp && searchComp1 == undefined) { // search_box가 존재하고 searchComp_1이 없을 때만 숨김
        searchBoxComp.hide();
    }

    // 테스트결함관리 조회 (페이지 로드 시 자동 조회)
    scwin.btn_search_onclick();
};

// 각 그리드별 페이지 정보 초기화
scwin.initPaginationInfo = function() {
    console.log("페이지 정보 초기화 시작");

    // 이 def.xml에서는 서버 페이징을 사용하는 것으로 보이므로, allDataPageInfo는 크게 사용되지 않음.
    // 그러나 통일성을 위해 유지하고, 클라이언트 페이징을 위해 waiting, processing, completed 정보를 사용.
    scwin.allDataPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 대기 데이터 페이지 정보 (클라이언트 페이징)
    scwin.waitingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 진행중 데이터 페이지 정보 (클라이언트 페이징)
    scwin.processingPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    // 완료 데이터 페이지 정보 (클라이언트 페이징)
    scwin.completedPageInfo = {
        currentPage: 1,
        pageSize: 10,
        totalCount: 0,
        data: []
    };

    console.log("페이지 정보 초기화 완료:", scwin.allDataPageInfo);
};

// 페이지별 데이터 분할 함수 (이 함수는 클라이언트 페이징을 위해 유지)
scwin.getPageData = function(data, pageInfo) {
    if (!data || !pageInfo) {
        console.error("getPageData: 데이터 또는 페이지 정보가 없습니다.", data, pageInfo);
        return [];
    }

    var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
    var endIndex = startIndex + pageInfo.pageSize;
    return data.slice(startIndex, endIndex);
};

// 페이지 네비게이터 업데이트 함수 (이 함수는 클라이언트 페이징을 위해 유지)
scwin.updatePagination = function(pageInfo, paginationComponent) {
    if (!pageInfo || !paginationComponent) {
        console.error("updatePagination: 페이지 정보 또는 컴포넌트가 없습니다.", pageInfo, paginationComponent);
        return;
    }

    var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);
    if (totalPages > 0) {
        paginationComponent.setCount(totalPages);
        paginationComponent.setSelectedIndex(pageInfo.currentPage);
    } else { // 데이터가 없을 때 페이지네이터 초기화
        paginationComponent.setCount(1);
        paginationComponent.setSelectedIndex(1);
    }
};

/************************** 이벤트 함수 *************************/

/**
 * 조회 버튼 클릭 이벤트
 */        
scwin.btn_search_onclick = function(e) {
    // 페이지 번호 초기화
    dmp_defVo.set("pageIndex","1");
    // pgl_defList.setSelectedIndex(1); // submitdone에서 처리하도록 변경

    // 서버통신 - 테스트결함관리 조회
    $c.sbm.execute($p, sbm_selectDefVoList);
};

scwin.sbm_defList_submitdone = function(e) {
    console.log("서버 응답 수신");

    // error 수신시
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;
    if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    var allData = elData.defVoList || [];
    console.log("전체 데이터:", allData.length, "개");

    // 클라이언트 페이징을 위한 데이터 분류
    var waitingData = [];     // NEW - 신규
    var processingData = [];  // IPR - 진행중
    var completedData = [];   // FIX, REO, CLS - 해결, 재오픈, 완료 (분류 기준 명확화)

    for(var i = 0; i < allData.length; i++) {
        var item = allData[i];
        if(item.status === "NEW") {
            waitingData.push(item);
        } else if(item.status === "IPR") {
            processingData.push(item);
        } else if(item.status === "COM") {
            completedData.push(item);
        }
    }
    console.log("신규:", waitingData.length, "진행중:", processingData.length, "완료:", completedData.length);

    // 각 그리드별 전체 데이터 저장 (안전하게) 및 현재 페이지 초기화
    scwin.waitingPageInfo.data = waitingData;
    scwin.waitingPageInfo.totalCount = waitingData.length;
    scwin.waitingPageInfo.currentPage = 1;

    scwin.processingPageInfo.data = processingData;
    scwin.processingPageInfo.totalCount = processingData.length;
    scwin.processingPageInfo.currentPage = 1;

    scwin.completedPageInfo.data = completedData;
    scwin.completedPageInfo.totalCount = completedData.length;
    scwin.completedPageInfo.currentPage = 1;

    // 각 그리드에 페이지별 데이터 설정
    scwin.updateGridData();

    // 페이지 네비게이터 업데이트 (각 그리드별로 분리)
    try {
        // 전체 데이터 그리드 네비게이터
        var mainTotalPageCount = Math.ceil(elData.totalCount / dmp_defVo.get("pageSize"));
        pgl_defList.setCount(mainTotalPageCount);
        pgl_defList.setSelectedIndex(parseInt(dmp_defVo.get("pageIndex")));

        // 칸반 보드는 클라이언트 페이징 정보 사용
        scwin.updatePagination(scwin.waitingPageInfo, pgl_defList_new);
        scwin.updatePagination(scwin.processingPageInfo, pgl_defList_processing);
        scwin.updatePagination(scwin.completedPageInfo, pgl_defList_completed);
    } catch (err) {
        console.error("페이지 네비게이터 업데이트 오류:", err);
    }

    // 카운트 업데이트
    spn_waitListCnt.setLabel(waitingData.length);
    spn_processingListCnt.setLabel(processingData.length);
    spn_completeListCnt.setLabel(completedData.length);
    spn_listCnt.setLabel(elData.totalCount);

    // 테스트결함관리 dataMap 초기화 및 readOnly 설정 (팝업 관련)
    dmp_defVoDetail.setEmptyValue();
    // HTML에 grp_defInfo가 팝업 외부에 없으므로, 이 부분은 팝업 로직에서만 처리하거나 제거
    // grp_defInfo.setReadOnly(false); // 팝업이 열릴 때 setReadOnly(false)가 되어야 함

    // 메인 화면 버튼 상태 초기화
    // HTML을 보면 메인 화면에는 '조회' (btn_search), '등록' (reg_btn, btn_register) 버튼만 직접적으로 존재합니다.
    // '저장', '수정', '삭제' 버튼 (btn_save, btn_edit, btn_delete)은 팝업 내에 있는 것으로 보입니다.
    // 따라서 이 부분은 메인 화면의 버튼 제어와는 무관하며, 팝업 관련 로직에서 제어되어야 합니다.
    // 메인 화면에서는 초기 상태로 '등록' 버튼만 존재하고 '수정/삭제' 버튼은 보이지 않습니다.
    // 이는 이 함수에서 직접 제어할 필요가 없거나, 팝업 관련 버튼을 제어하도록 변경되어야 합니다.
    // 현재 HTML에는 btn_save (팝업내), btn_popup_edit, btn_popup_delete 가 팝업 내에 있습니다.
    // 이 함수는 '조회 완료 후'의 메인 화면 상태를 정의하므로, 팝업 버튼을 직접 제어하지 않습니다.

    spn_registerFlag.setValue("등록"); // 등록 모드 플래그

    // 페이징 정보 업데이트 (전체 목록 그리드용)
    var totalPageCount = Math.ceil(elData.totalCount / dmp_defVo.get("pageSize"));
    spn_totalPageCount.setValue(totalPageCount);
    spn_pageIndex.setValue(parseInt(dmp_defVo.get("pageIndex")));
    pgl_defList.setSelectedIndex(parseInt(dmp_defVo.get("pageIndex"))); // 페이지네이터 선택 상태 업데이트
};

// 각 그리드 데이터 업데이트 (클라이언트 페이징을 위해 getPageData 사용)
scwin.updateGridData = function() {
    console.log("그리드 데이터 업데이트 시작");

    try {
        // 전체 데이터 그리드 (서버 페이징)
        if (dlt_defVoList) { // dlt_defVoList는 submission target에서 바로 받아오므로 여기서 별도 getPageData 불필요
            console.log("전체 데이터 그리드 업데이트 (Submission Target):", dlt_defVoList.getRowCount(), "개");
        }

        // 신규 그리드 (클라이언트 페이징)
        if (scwin.waitingPageInfo && scwin.waitingPageInfo.data) {
            var waitingPageData = scwin.getPageData(scwin.waitingPageInfo.data, scwin.waitingPageInfo);
            dlt_waitingList.setJSON(waitingPageData);
            console.log("신규 그리드 업데이트:", waitingPageData.length, "개");
        }

        // 진행중 그리드 (클라이언트 페이징)
        if (scwin.processingPageInfo && scwin.processingPageInfo.data) {
            var processingPageData = scwin.getPageData(scwin.processingPageInfo.data, scwin.processingPageInfo);
            dlt_processingList.setJSON(processingPageData);
            console.log("진행중 그리드 업데이트:", processingPageData.length, "개");
        }

        // 완료 그리드 (클라이언트 페이징)
        if (scwin.completedPageInfo && scwin.completedPageInfo.data) {
            var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
            dlt_completedList.setJSON(completedPageData);
            console.log("완료 그리드 업데이트:", completedPageData.length, "개");
        }
    } catch (err) {
        console.error("그리드 데이터 업데이트 오류:", err);
    }
};

/**
 * 페이지 번호 클릭 이벤트 (메인 그리드)
 */
scwin.pgl_defList_onclick = function(idx) {
    console.log("전체 데이터 페이지 클릭:", idx);

    // 페이지 번호 세팅
    dmp_defVo.set("pageIndex", idx);

    // 서버통신 - 테스트결함관리 조회
    $c.sbm.execute($p, sbm_selectDefVoList);
};

// 신규 데이터 페이지 클릭 (클라이언트 페이징)
scwin.pgl_defList_new_onclick = function(idx) {
    console.log("신규 데이터 페이지 클릭:", idx);

    if (!scwin.waitingPageInfo) {
        console.error("신규 페이지 정보가 없습니다.");
        return;
    }

    scwin.waitingPageInfo.currentPage = idx;

    // 신규 그리드만 업데이트
    var waitingPageData = scwin.getPageData(scwin.waitingPageInfo.data, scwin.waitingPageInfo);
    dlt_waitingList.setJSON(waitingPageData);

    // 페이지 네비게이터 선택 상태 업데이트
    pgl_defList_new.setSelectedIndex(idx);
};

// 진행중 데이터 페이지 클릭 (클라이언트 페이징)
scwin.pgl_defList_processing_onclick = function(idx) {
    console.log("진행중 데이터 페이지 클릭:", idx);

    if (!scwin.processingPageInfo) {
        console.error("진행중 페이지 정보가 없습니다.");
        return;
    }

    scwin.processingPageInfo.currentPage = idx;

    // 진행중 그리드만 업데이트
    var processingPageData = scwin.getPageData(scwin.processingPageInfo.data, scwin.processingPageInfo);
    dlt_processingList.setJSON(processingPageData);

    // 페이지 네비게이터 선택 상태 업데이트
    pgl_defList_processing.setSelectedIndex(idx);
};

// 완료 데이터 페이지 클릭 (클라이언트 페이징)
scwin.pgl_defList_completed_onclick = function(idx) {
    console.log("완료 데이터 페이지 클릭:", idx);

    if (!scwin.completedPageInfo) {
        console.error("완료 페이지 정보가 없습니다.");
        return;
    }

    scwin.completedPageInfo.currentPage = idx;

    // 완료 그리드만 업데이트
    var completedPageData = scwin.getPageData(scwin.completedPageInfo.data, scwin.completedPageInfo);
    dlt_completedList.setJSON(completedPageData);

    // 페이지 네비게이터 선택 상태 업데이트
    pgl_defList_completed.setSelectedIndex(idx);
};


// 테스트결함관리 초기화 (팝업 상세 정보 초기화 및 버튼 상태 설정)
scwin.btn_reset_onclick = function(e) {
    // 테스트결함관리 dataMap 초기화
    dmp_defVoDetail.setEmptyValue();

    // 테스트결함관리 readOnly false
    // HTML에 grp_defInfo는 팝업 내에 있으므로, 팝업 내 폼 그룹 ID 사용
    var grpDefInfoPopup = $p.getComponentById("grp_popupForm"); // 팝업 내 상세 정보 그룹 ID
    if (grpDefInfoPopup) {
        grpDefInfoPopup.setReadOnly(false);
    }

    // 팝업 내 버튼 상태 설정: 등록 모드
    var popupSaveBtn = $p.getComponentById("btn_save"); // 팝업 내 저장 버튼 ID가 btn_save로 되어있음
    var popupEditBtn = $p.getComponentById("btn_popup_edit");
    var popupDeleteBtn = $p.getComponentById("btn_popup_delete");

    if (popupSaveBtn) popupSaveBtn.show();
    if (popupEditBtn) popupEditBtn.hide();
    if (popupDeleteBtn) popupDeleteBtn.hide();

    // 추가: 팝업 제목을 '등록'으로 설정
    spn_popupTitle.setValue("테스트결함 등록");

    spn_registerFlag.setValue("등록"); // 플래그 설정은 유지
    dlt_Upload.setJSON([]); // 파일 목록 초기화
};

/**
 * 그리드 셀 클릭 이벤트 (메인 그리드)
 */
scwin.grd_list_oncellclick = function(row,col,colId) {
    dmp_defVoDetail.setJSON(dlt_defVoList.getRowJSON(row));

    // 메인 그리드 셀 클릭 시 (상세 뷰가 아닌, 메인 화면 하단 폼으로 데이터 로드)
    // 메인 화면에는 저장/수정/삭제 버튼이 직접 보이지 않으므로, 이 부분은 팝업의 버튼과 혼동되지 않도록 주의
    // HTML상 메인 화면에는 별도의 수정/삭제 버튼이 없고, 팝업을 통해 수정/삭제를 하는 것으로 보입니다.
    // 만약 메인 화면 하단에 폼이 있고 그 폼에 수정/삭제 버튼이 있다면 해당 ID를 사용해야 합니다.
    // 현재 스크립트에서는 'grd_list_oncellclick'이 메인 화면 하단의 폼에 데이터를 바인딩하고,
    // 그 폼에 'btn_save', 'btn_edit', 'btn_delete'가 있다고 가정하는 것 같습니다.
    // 하지만 HTML에 grp_issInfo (여기서는 grp_defInfo)는 있지만 해당 버튼들은 직접 보이지 않습니다.
    // 이 함수가 메인 화면의 버튼을 제어한다면, HTML에서 해당 버튼들을 찾아서 $p.getComponentById로 참조해야 합니다.
    // HTML 구조상 이 함수에서 제어하는 btn_save, btn_edit, btn_delete는 팝업 내 버튼과 동일 ID를 가질 수 있어 혼란을 야기할 수 있습니다.
    // 일단 현재 HTML을 기준으로 팝업 내 버튼이 아닌 메인 화면 하단에 숨겨진(?) 버튼이라고 가정하고 $p.getComponentById를 추가합니다.
    var mainBtnSave = $p.getComponentById("btn_save_main"); // 메인 화면의 저장 버튼 (임의의 ID 부여)
    var mainBtnEdit = $p.getComponentById("btn_edit_main"); // 메인 화면의 수정 버튼
    var mainBtnDelete = $p.getComponentById("btn_delete_main"); // 메인 화면의 삭제 버튼

    if (mainBtnSave) mainBtnSave.hide();
    if (mainBtnEdit) mainBtnEdit.show();
    if (mainBtnDelete) mainBtnDelete.show();

    spn_registerFlag.setValue("수정");
};


/**
 * 저장 버튼 클릭 이벤트 (팝업 내에서 사용되는 저장 버튼)
 */ 
scwin.btn_save_onclick = function(e) {
    // 유효성 체크
    var valInfo = [
        { id: "id", mandatory: true }
    ];

    // 유효성 검사 그룹을 팝업 내의 상세 정보 그룹으로 지정
    var grpDefInfoPopup = $p.getComponentById("grp_popupForm");
    if ($c.data.validateGroup(grpDefInfoPopup, valInfo) === true) {
        var promise = $c.win.confirm("저장하시겠습니까?");
        promise.then(function(result) {  
            if (result){
                $c.sbm.execute(sbm_insertDefVo);
            }
        });
    }  
};

/**
 * 등록 완료 콜백
 */
scwin.sbm_insertDefVo_submitdone = function(e) {
    // error 수신시
    var elHeader = e.responseJSON.elHeader;
    if(elHeader == null || elHeader == "" || elHeader == "undefiend" || elHeader.resSuc == false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }else{
        // 등록되었습니다. msg 출력
        $c.win.alert("등록되었습니다.");
    }

    pop_overlay.hide(); // 팝업 닫기
    // 재조회 (모든 그리드 새로고침)
    scwin.btn_search_onclick();
};

