// 메인 화면의 '등록' 버튼 클릭 시 팝업 열기
scwin.reg_btn_onclick = function (e) {
    // 상세 정보 초기화
    dmp_defVoDetail.setEmptyValue();

    // 시연용 데이터 설정 (원하시는 대로 유지)
    dmp_defVoDetail.set("pjtId", "6");
    dmp_defVoDetail.set("pjtName", "ERP 시스템 고도화 프로젝트");
    dmp_defVoDetail.set("userId", "1");
    dmp_defVoDetail.set("userName", "김개발");

    dlt_Upload.setJSON([]); // 파일 업로드 목록 초기화

    // 팝업 제목 설정
    spn_popupTitle.setValue("테스트결함 등록");

    // 팝업 내 버튼 상태 설정: 등록 모드
    var popupSaveBtn = $p.getComponentById("btn_save"); // 팝업 내 저장 버튼 ID
    var popupEditBtn = $p.getComponentById("btn_popup_edit");
    var popupDeleteBtn = $p.getComponentById("btn_popup_delete");

    if (popupSaveBtn) popupSaveBtn.show();
    if (popupEditBtn) popupEditBtn.hide();
    if (popupDeleteBtn) popupDeleteBtn.hide();

    pop_overlay.show(); // 팝업 표시
};

