// 메인 그리드 (전체 목록)의 상태 컬럼 렌더링
scwin.grd_list_onrenderrow = function(rowIndex) {
    var statusValue = dlt_defVoList.getCellData(rowIndex, "status");
    var cell = grd_list.getCell(rowIndex, "status");

    if (!cell) return;

    // 기존 텍스트 지우기
    cell.innerHTML = "";

    // 상태에 따른 span 생성
    var spanHtml = "";
    switch(statusValue) {
        case "NEW":
            spanHtml = '<span style="background: #e6f3ff; color: #0066cc; padding: 2px 5px; border: 1px solid #b3d9ff; font-size: 10px; margin-right: 5px; border-radius: 3px;">신규</span>';
            break;
        case "IPR": // 진행중
            spanHtml = '<span style="background: #fff2e6; color: #cc6600; padding: 2px 5px; border: 1px solid #ffcc99; font-size: 10px; margin-right: 5px; border-radius: 3px;">진행중</span>';
            break;
        case "COM": // 완료
            spanHtml = '<span style="background: #f2e6ff; color: #6600cc; padding: 2px 6px; border: 1px solid #cc99ff; font-size: 10px; font-weight: bold; margin-right: 5px; border-radius: 3px;">완료</span>';
            break;
        default:
            spanHtml = statusValue; // 매핑되지 않은 값은 그대로 표시
    }

    cell.innerHTML = spanHtml;
};


